import java.io.*;
import java.util.*;

public final class CF_630_D2_E_V4 {

    private static final boolean DEBUG = false;
    private static PrintWriter pw;
    private static Reader sc;

    private static void dbug(Object... o) {
        if (DEBUG) {
            for (Object x : o) System.err.print(x + " ");
            System.err.println();
        }
    }

    private static long fastPow(long b, long e, long m) {
        long r = 1;
        b %= m;
        while (e > 0) {
            if ((e & 1) == 1) r = (r * b) % m;
            b = (b * b) % m;
            e >>= 1;
        }
        return r;
    }

    private static void execute() throws IOException {
        pw = new PrintWriter(System.out);
        sc = new Reader(System.in);

        long n = sc.nextLong();
        long m = sc.nextLong();
        int L = sc.nextInt();
        int R = sc.nextInt();

        long MOD = 998244353L;
        long total = n * m;
        long inv2 = fastPow(2, MOD - 2, MOD);

        long len = R - L + 1;
        long odds = len / 2;
        long evens = len - odds;

        long res;
        if (total % 2 == 1) {
            res = fastPow(len, total, MOD);
        } else {
            long t1 = fastPow(len, total, MOD);
            long t2 = fastPow(Math.abs(evens - odds), total, MOD);
            res = (t1 + t2) % MOD;
            res = (res * inv2) % MOD;
        }

        pw.println(res);
        pw.close();
    }

    public static void main(String[] args) throws IOException {
        execute();
    }

    static class Reader {
        private final InputStream in;
        private final byte[] buf = new byte[1 << 15];
        private int p = 0, len = 0;

        Reader(InputStream in) {
            this.in = in;
        }

        private int get() throws IOException {
            if (p >= len) {
                p = 0;
                len = in.read(buf);
                if (len <= 0) return -1;
            }
            return buf[p++];
        }

        private void eat() throws IOException {
            int c;
            while ((c = get()) <= 32 && c != -1) {}
            p--;
        }

        public int nextInt() throws IOException {
            eat();
            boolean neg = false;
            int c = get();
            if (c == '-') {
                neg = true;
                c = get();
            }
            int x = 0;
            while (c >= '0' && c <= '9') {
                x = x * 10 + (c - '0');
                c = get();
            }
            return neg ? -x : x;
        }

        public long nextLong() throws IOException {
            eat();
            boolean neg = false;
            int c = get();
            if (c == '-') {
                neg = true;
                c = get();
            }
            long x = 0;
            while (c >= '0' && c <= '9') {
                x = x * 10 + (c - '0');
                c = get();
            }
            return neg ? -x : x;
        }
    }
